const slug=(s:string)=>s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');

const guardBottomInstruction:Record<string,Partial<BjjTechnique>>={
'Cross choke':{goal:'Use opposing collar grips from closed guard to control posture and apply a blood choke while keeping the opponent trapped between your legs.',setup:'Begin in closed guard with posture controlled. Create access to both sides of the collar before committing both hands.',grips:['Feed the first hand deep into the opposite collar, palm up, aiming to bring the wrist/forearm close to the side of the neck.','The second hand reaches underneath or over the first arm to the opposite collar. Keep both elbows structurally close rather than flaring.'],baseManipulation:'Break posture so the opponent cannot simply sit tall and pull their neck away. Your closed guard and knees keep their torso connected to you while the grips occupy both sides of the neck.',bodyPosition:'Stay connected underneath the opponent with your shoulders active and knees drawing them toward you. Do not sacrifice all hip control just to reach deeper.',steps:['Break posture and open the collar enough to establish the first deep cross-collar grip.','Secure the second collar grip on the opposite side.','Keep your wrists aligned along the sides of the neck and elbows close.','Use your guard and upper body to keep the opponent’s posture down.','Draw the elbows toward your ribs/hips while expanding your chest and keeping the forearms connected to the neck.','Apply gradually and release immediately on the tap.'],finish:'Maintain closed-guard control while gradually tightening both sides of the neck; do not explosively yank the collars.',mechanism:'The two forearms/wrists compress the carotid regions from opposite sides while posture control prevents the opponent from creating space.',cues:['First grip deep.','Break posture before chasing the second grip.','Elbows close.','Use the guard to keep them connected.'],mistakes:['First grip too shallow.','Trying to squeeze with the arms while the opponent is upright.','Flaring the elbows and creating space.'],troubleshooting:[{problem:'My arms burn but there is little choking pressure.',fix:'Check grip depth, wrist position, and posture control before squeezing harder.'},{problem:'They posture out while I reach for the second grip.',fix:'Re-break posture and use your legs before committing the second hand.'}],reactions:['If they defend the second grip, use the hand fight to create angles for armbar/triangle attacks.'],followUps:['Armbar from closed guard','Triangle from closed guard','Scissor Sweep'],variations:['Palm-up cross choke','Academy-specific over/under second-hand finishes'],drilling:['Practice first-grip depth and posture breaking without finishing.','Add the second grip and slow finish with immediate release.']},
'Armbar from closed guard':{goal:'Isolate one arm, control the opponent’s posture and shoulder line, then use your hips and legs to apply elbow extension.',setup:'Begin in closed guard with posture broken enough to control one arm above the elbow line.',grips:['Control the target arm at wrist/sleeve and above the elbow as appropriate.','Use a head/collar/shoulder connection to keep the opponent from simply posturing away while you create the angle.'],baseManipulation:'Pull the target arm across/into your center while controlling posture. Your angle removes the opponent’s ability to stack squarely before your legs are in position.',bodyPosition:'Pivot your hips so your body becomes perpendicular rather than staying square underneath. One leg controls the upper back/shoulder; the other clears over the head.',steps:['Break posture and isolate the target arm.','Keep the elbow above your hip line and prevent the arm from retracting.','Open the guard and pivot your hips to create a strong angle.','Bring the near leg high over the opponent’s back/shoulder to control posture.','Swing the other leg over the head without releasing the arm.','Pinch the knees and control the wrist so the thumb/elbow orientation is correct.','Control posture before extending the hips gradually for the finish.'],finish:'Keep the knees connected, heels active, and extend the hips gradually against the elbow joint. Release immediately on the tap.',mechanism:'Your hips become the fulcrum under the elbow while your legs control the opponent’s head/shoulders and the wrist prevents the arm from rotating free.',cues:['Elbow above your hips.','Angle first.','Leg over the head before extending.','Knees tight; finish slowly.'],mistakes:['Trying to armbar while square underneath.','Crossing the ankles loosely and letting the knees separate.','Losing the arm while swinging the leg over the head.','Extending before controlling posture.'],troubleshooting:[{problem:'They pull the arm free.',fix:'Keep the elbow captured above your hip line and maintain wrist/upper-arm control during the pivot.'},{problem:'They stack me.',fix:'Create the angle earlier and keep posture controlled with the leg over the upper back/head.'}],reactions:['If they retract the elbow, transition to triangle/omoplata opportunities created by the arm movement.'],followUps:['Triangle from closed guard','Omoplata','Sweep from failed armbar'],variations:['Standard closed-guard armbar','Angle armbar'],drilling:['Pause at each checkpoint: arm isolated, angle created, leg over head, knees connected.','Add posture resistance before adding full submission resistance.']},
'Triangle from closed guard':{goal:'Trap the opponent’s neck and one arm between your legs, create an angle, and compress both sides of the neck.',setup:'Begin in closed guard and create a one-arm-in/one-arm-out relationship while controlling posture.',grips:['Control wrists/sleeves or collar/head as needed to put one arm inside your leg line and the other outside.','Once the triangle is entered, control the head/posture so the opponent cannot simply rise away.'],baseManipulation:'Break posture and isolate one shoulder inside the choke. Cutting an angle makes the trapped shoulder help close one side of the neck.',bodyPosition:'Bring one leg over the neck/shoulder, lock the figure-four with the other leg, then pivot so you are looking more toward the opponent’s ear than straight up their centerline.',steps:['Break posture and establish one arm in, one arm out.','Bring the choking leg high over the opponent’s neck/shoulder.','Control the head/posture and lift your hips if needed to clear the arm.','Lock your ankle behind the opposite knee rather than over the foot.','Pivot your hips to create an angle and bring the opponent’s trapped arm across as appropriate.','Pull the shin/knee line into position, flex the feet, and squeeze the knees while maintaining posture control.','Finish gradually and release on the tap.'],finish:'Use angle and leg structure, not only adductor strength. Maintain head control until the choke is secure.',mechanism:'One thigh compresses one side of the neck while the opponent’s trapped shoulder is driven into the other; the figure-four closes the space.',cues:['One arm in, one arm out.','Leg high on the neck.','Angle before squeeze.','Lock behind the knee, not on the foot.'],mistakes:['Staying square underneath.','Triangle locked over the foot/ankle incorrectly.','Opponent’s shoulder not driven into the neck.','Trying to squeeze before controlling posture.'],troubleshooting:[{problem:'There is lots of space around the neck.',fix:'Re-angle, pull the shin tighter, and ensure the trapped shoulder is actually inside the choke structure.'},{problem:'They posture up.',fix:'Control the head/posture before spending energy squeezing.'}],reactions:['If they hide the trapped arm or turn, use the angle for armbar/omoplata transitions.'],followUps:['Armbar from closed guard','Omoplata','Sweep'],variations:['Standard triangle','Angle/cutting triangle'],drilling:['Drill one-arm-in entry and angle before finishing.','Add partner posture resistance progressively.']},
'Kimura from closed guard':{goal:'Control the wrist and shoulder with a figure-four, create an angle, and apply controlled internal shoulder rotation.',setup:'Begin in closed guard when the opponent posts a hand or leaves an arm available near the mat.',grips:['Secure the opponent’s wrist with your same-side hand.','Reach over/around the upper arm with your other hand and grip your own wrist to form the figure-four.'],baseManipulation:'Sit up and connect your torso to the opponent’s shoulder so they cannot simply straighten the arm or posture away. Break their hand/arm away from a strong post.',bodyPosition:'Angle your hips and upper body toward the trapped arm. Keep the opponent’s elbow bent and your figure-four tight to your body.',steps:['Control the wrist and sit up toward the target shoulder.','Reach over the upper arm and secure your own wrist.','Break the opponent’s posture/hand away from a strong posting position.','Angle your body and keep the elbow bent.','Bring the wrist behind the opponent’s back while keeping the elbow controlled.','Rotate the shoulder gradually without separating your figure-four.'],finish:'Apply slow shoulder rotation while controlling the wrist and elbow. Release immediately on the tap.',mechanism:'The figure-four fixes the wrist and elbow, allowing your body to rotate the humerus at the shoulder while the opponent’s torso is controlled.',cues:['Two-on-one figure-four.','Sit up and connect.','Angle your body.','Move the shoulder, not just the hand.'],mistakes:['Trying to finish while flat.','Loose figure-four.','Letting the opponent straighten the arm.','Cranking the hand without controlling the elbow/shoulder.'],troubleshooting:[{problem:'They straighten the arm.',fix:'Keep the elbow bent and your torso connected; transition if the arm shape is lost rather than forcing it.'}],reactions:['A straightening arm can create alternate arm attacks or posture openings.','If they roll to relieve pressure, follow to top control.'],followUps:['Hip bump / sit-up sweep','Armbar from closed guard','Back take'],variations:['Closed-guard Kimura','Kimura sweep when opponent rolls/posts'],drilling:['Build the figure-four and angle without finishing.','Add controlled resistance to posture and arm straightening.']},
'Guillotine from closed guard':{goal:'Control the opponent’s head/neck as posture collapses and use your arms, torso, and guard to apply a controlled front-head choke.',setup:'Enter when the opponent’s head comes low or you can snap/control it below your chest/arm line.',grips:['Wrap the neck with the choking arm and secure an appropriate guillotine grip taught by your academy.','Use the second hand to reinforce the choking hand/wrist while keeping the opponent’s head captured.'],baseManipulation:'Keep the opponent’s posture folded and prevent them from driving their head/shoulder to a safe side. Your guard controls distance and limits their ability to circle free.',bodyPosition:'Keep the choking-side connection tight and use your torso angle rather than pulling only with the arms. Closed guard may be used to control the hips while you adjust.',steps:['Capture the head as the opponent’s posture lowers.','Secure your guillotine grip without leaving large space around the neck.','Control their hips/posture with your guard.','Adjust your angle so your torso and forearm structure reinforce the choke.','Keep the head trapped and remove slack from the grip.','Apply pressure gradually according to the guillotine variation.'],finish:'Finish with controlled pressure and release immediately on the tap; neck attacks should never be applied explosively.',mechanism:'The grip and torso position compress the neck while the guard prevents the opponent from easily posturing/circling away.',cues:['Capture posture first.','Remove slack.','Use your torso, not only your arms.','Finish slowly.'],mistakes:['Trying to pull the head off with arm strength.','Allowing the opponent to posture/circle to the safe side.','Loose grip with space around the neck.'],troubleshooting:[{problem:'My arms fatigue quickly.',fix:'Reassess grip depth, torso angle, and hip control instead of squeezing harder.'}],reactions:['If they defend the neck and drive forward, use the reaction to sweep or improve top position rather than burning out your arms.'],followUps:['Hip bump / sit-up sweep','Sweep to top','Front headlock'],variations:['Arm-in and arm-out guillotine structures vary; use your academy’s preferred mechanics.'],drilling:['Practice capture and grip placement without finishing.','Add posture/circling defense at low resistance.']},
'Omoplata':{goal:'Use your legs to isolate an arm and rotate the opponent’s shoulder while controlling their posture and ability to roll away.',setup:'Enter from guard when one arm can be separated and your leg can pass over the opponent’s shoulder line.',grips:['Control the target wrist/sleeve so the arm remains trapped as your leg clears the shoulder.','Control the waist/belt/hip or far side as needed to prevent the opponent from simply rolling or posturing out.'],baseManipulation:'Break posture and turn the opponent’s shoulder toward the mat. Prevent their forward roll/escape before trying to finish.',bodyPosition:'Pivot so your legs point away from the opponent rather than staying square. Sit up toward their hip/back while keeping the trapped shoulder connected to your legs.',steps:['Isolate the target arm and create enough angle for your leg to clear the shoulder.','Bring the leg over the shoulder and trap the arm between your thighs.','Pivot your hips so you face away/alongside the opponent.','Sit up and control the opponent’s waist/hip to prevent the roll.','Flatten or lower their posture toward the mat.','Scoot/angle your hips away as needed while keeping the shoulder trapped.','Apply gradual shoulder rotation by sitting forward/up with control.'],finish:'Control the roll first, then apply the shoulder lock gradually. Release immediately on the tap.',mechanism:'Your legs control the upper arm while your body rotation fixes the shoulder and turns the opponent’s torso away from the trapped limb.',cues:['Angle before finish.','Control the roll.','Sit up—do not stay flat.','Keep the shoulder trapped.'],mistakes:['Trying to finish while square/flat.','Failing to control the opponent’s hip/waist.','Letting the arm slip free during the pivot.'],troubleshooting:[{problem:'They forward-roll out.',fix:'Control the hip/waist and sit up before applying the finish.'},{problem:'I cannot sit up.',fix:'Create more hip angle and use your free hand/leg to build height rather than pulling only on the arm.'}],reactions:['If they roll, follow and establish top position.','If they posture before the shoulder is trapped, return to guard attacks instead of forcing it.'],followUps:['Triangle from closed guard','Armbar from closed guard','Top control after roll'],variations:['Standard omoplata','Omoplata sweep'],drilling:['Drill the pivot and sit-up separately from the submission.','Add roll prevention, then progressive escape resistance.']},
'Hip bump / sit-up sweep':{goal:'Exploit an opponent who postures back by sitting up, controlling a posting arm, and driving your hips through their base to reverse to top.',setup:'Begin in closed guard as the opponent’s torso becomes upright or their weight shifts backward.',grips:['Post one hand behind you for base as you sit up.','Use the other arm to control/trap the opponent’s arm on the sweep side, commonly overhooking or controlling near the elbow so they cannot post.'],baseManipulation:'The opponent’s backward posture puts weight behind their knees. Trap the arm they need to post and drive your hips diagonally through the remaining base.',bodyPosition:'Sit up tall and bring your chest close to the opponent rather than trying to sweep from your back. Your hips must rise off the mat and connect to their torso.',steps:['Recognize the opponent sitting/posturing backward.','Open the guard and sit up quickly, posting one hand behind you.','Bring your hips close to the opponent and control the posting arm on the sweep side.','Plant your feet/leg position so you can elevate the hips.','Drive your hips up and diagonally through the opponent while rotating toward the trapped-arm side.','Follow the opponent to the mat and establish mount/top control.'],finish:'Come all the way to top; do not celebrate the tip while remaining seated.',mechanism:'You remove the opponent’s near post while your rising hips move their center beyond the backward/side edge of their kneeling base.',cues:['They posture back → you sit up.','Hip to chest.','Trap the post.','Drive diagonally, then follow.'],mistakes:['Trying to sweep from flat guard.','Sitting up but leaving the hips far away.','Failing to trap the posting arm.','Falling back after they tip.'],troubleshooting:[{problem:'They post and stop the sweep.',fix:'Control the arm on the sweep side before driving.'},{problem:'I cannot move their weight.',fix:'Get your hips closer and higher; the movement is a hip drive, not an arm pull.'}],reactions:['If they drive forward to stop your sit-up, use the posture change for guillotine/Kimura/closed-guard attacks.'],followUps:['Kimura from closed guard','Guillotine from closed guard','Mount'],variations:['Hip-bump sweep','Sit-up sweep'],drilling:['Partner alternates upright and forward posture; choose hip bump only on the upright reaction.','Finish every rep by stabilizing mount.']},
'Flower sweep':{goal:'Use an isolated arm, a strong hip angle, and leg elevation to rotate a kneeling opponent over a compromised post into top position.',setup:'Begin in closed guard with posture controlled and one arm isolated so the opponent cannot post freely on the sweep side.',grips:['Control the sleeve/wrist on the side that must not post.','Use the other hand to control the opposite leg/pants or upper body according to your academy’s version.'],baseManipulation:'Take away one hand post and elevate/redirect the opponent’s weight while controlling a leg or far-side base so they cannot widen out.',bodyPosition:'Pivot your hips to create an angle. Your sweeping leg should be able to make a broad pendulum/flower motion rather than pushing straight upward.',steps:['Break posture and control the posting arm.','Create an angle by pivoting your hips.','Secure the leg/pants or other secondary control used in your version.','Open the guard while keeping upper-body connection.','Swing the free leg in a broad arc to generate rotation and lift.','Use the grips to guide the opponent over the missing post.','Follow the rotation immediately to mount/top.'],finish:'Arrive on top with control, commonly mount, and stabilize before releasing grips.',mechanism:'The isolated arm removes a post while the leg arc and hip angle rotate the opponent’s center over the remaining base.',cues:['Kill the post.','Create angle.','Big relaxed leg arc.','Follow to top.'],mistakes:['Trying to muscle the opponent with a small leg movement.','No hip angle.','Letting go of the posting arm too early.'],troubleshooting:[{problem:'They catch themselves.',fix:'Recheck the arm/post control and whether your secondary grip is limiting their base.'}],reactions:['If the opponent retracts the controlled arm, use the movement to transition to another guard attack.'],followUps:['Mount','Armbar from closed guard','Pendulum sweep'],variations:['Flower sweep with pants/leg control','Armbar-to-flower sweep connection'],drilling:['Practice the hip pivot and leg arc without resistance.','Add post-control resistance progressively.']},
'Pendulum sweep':{goal:'Use a strong perpendicular angle and pendulum leg motion to elevate/rotate the opponent while controlling the arm and far-side base.',setup:'Begin from closed guard with one arm isolated and posture sufficiently controlled to create a deep angle.',grips:['Control the arm on the sweep side so it cannot post.','Use the other hand to control the far leg/pants or another anchor that limits the opponent’s base.'],baseManipulation:'Remove the hand post and control the far leg while your legs rotate the torso over the remaining base.',bodyPosition:'Pivot deeply so your torso is angled across the opponent. One leg helps load/elevate while the other swings in a pendulum arc.',steps:['Control the posting arm and break posture.','Pivot to a strong angle rather than remaining square.','Secure the far leg/pants/base.','Open the guard while maintaining connection.','Use one leg to load/elevate the opponent and swing the other leg in a broad pendulum motion.','Rotate the opponent toward the missing post.','Follow immediately into mount/top control.'],finish:'Complete the rotation and stabilize top position before transitioning.',mechanism:'The deep angle turns your legs into long levers while the controlled arm and leg prevent the opponent from rebuilding a wide base.',cues:['Deep angle.','Control arm and far base.','Pendulum, do not leg-press.','Come up with them.'],mistakes:['Staying square.','Small, tense leg swing.','Losing the arm post.'],troubleshooting:[{problem:'The opponent feels too heavy.',fix:'Increase your angle and load their weight before trying to swing them.'}],reactions:['The same angle can connect to armbar attacks if the opponent resists the sweep.'],followUps:['Armbar from closed guard','Flower sweep','Mount'],variations:['Pendulum sweep','Pendulum-to-armbar chain'],drilling:['Drill the angle and pendulum leg motion slowly.','Add controlled base resistance.']},
'Balloon sweep':{goal:'Use an opponent’s forward pressure and your feet/legs as elevation points to lift their center and redirect them overhead or to the side into top position.',setup:'Use when the opponent is standing or driving forward in a posture your academy teaches for the balloon sweep. Maintain grips before placing the feet.',grips:['Use secure sleeve/collar or upper-body grips that keep the opponent connected while you elevate.','Control enough of the arms that the opponent cannot simply post or disengage as their weight comes forward.'],baseManipulation:'Invite/load the opponent’s weight forward over your hips, then elevate at the moment their center passes over their feet/base.',bodyPosition:'Keep your hips underneath the opponent’s center and your feet placed on safe, effective elevation points taught by your coach; do not extend the knees prematurely.',steps:['Establish grips and manage the opponent’s standing/forward posture.','Place your feet at the appropriate hip/torso elevation points.','Draw the opponent’s weight forward over your hips.','Keep your knees bent until their center is loaded.','Extend/elevate with the legs while guiding with the grips.','Redirect their body past the point where their feet can recover underneath them.','Follow the sweep and establish top control.'],finish:'Use controlled elevation and guide the landing; follow safely to top rather than launching the partner uncontrolled.',mechanism:'The feet act as lifting frames underneath the opponent’s center while the grips prevent disengagement and steer their rotation.',cues:['Load first, extend second.','Hips underneath their center.','Guide the landing.','Control both people’s safety.'],mistakes:['Extending the legs before the opponent is loaded.','Using explosive launch force without steering.','Loose grips that allow disengagement.'],troubleshooting:[{problem:'They simply step back.',fix:'You tried to elevate before their weight committed forward.'}],reactions:['If they refuse forward pressure, transition to other open-guard controls rather than forcing elevation.'],followUps:['Open guard','Top control'],variations:['Academy-specific balloon sweep direction and foot placement'],drilling:['Practice loading/elevation with a cooperative partner and controlled landing.','Add forward-pressure timing gradually.']},
'Ankle pull sweep':{goal:'Exploit a standing opponent by controlling their ankles/posts while disrupting upper-body balance so their feet cannot follow their center.',setup:'Begin from an open/seated/supine guard relationship against a standing opponent.',grips:['Control one or both ankles/pant cuffs according to the version.','Use a collar/sleeve/upper-body connection when available to move the torso opposite the controlled feet.'],baseManipulation:'Fix the feet in place while pulling/pushing the upper body beyond the support line, or remove an ankle as their weight shifts.',bodyPosition:'Stay close enough that your legs can manage distance and you can come up immediately once the opponent sits/falls.',steps:['Establish ankle/pant controls before the opponent freely circles away.','Use your feet/legs and upper-body connection to make the opponent shift weight.','Pull or block the ankle that needs to remain behind as their torso moves.','Guide the opponent backward or sideways beyond their base.','Release/adjust the grips only as needed to come up.','Technical stand or wrestle up immediately into top position.'],finish:'Come to top before the opponent can rebuild a standing base.',mechanism:'A standing person recovers balance by stepping. Controlling the ankle removes that recovery step while their center moves outside the feet.',cues:['Control the step.','Move torso and feet in different directions.','Come up immediately.'],mistakes:['Pulling ankles while the opponent’s center remains perfectly stacked.','Staying seated after they fall.'],troubleshooting:[{problem:'They keep their balance.',fix:'Create upper-body movement first; ankle control alone is not enough if their center remains over the feet.'}],reactions:['If they step the free leg, follow the new base into tripod/sickle-style attacks.'],followUps:['Tripod sweep','Sickle sweep','Technical stand-up'],variations:['Double ankle pull','Single ankle control with upper-body off-balance'],drilling:['Partner stands; create a weight shift before attempting the ankle removal.','Finish every rep by coming to top.']},
'Tripod sweep':{goal:'Control a standing opponent’s ankle while one foot disrupts the hip and the other blocks/hooks the opposite leg, creating a three-point off-balance.',setup:'Begin in open guard against a standing opponent with access to an ankle and hip line.',grips:['Control the ankle on the sweep side firmly enough that the foot cannot step away.','Maintain a sleeve/collar or secondary control when useful, but prioritize the ankle/base relationship.'],baseManipulation:'One foot pushes the hip, the other blocks/hooks the opposite leg, and the hand fixes the near ankle. The opponent cannot step in the direction their center is being moved.',bodyPosition:'Stay square enough to manage both legs but mobile enough to follow the fall. Keep your hips close enough that the hip foot has meaningful leverage.',steps:['Secure the near ankle.','Place one foot on the opponent’s hip on the controlled-ankle side.','Place the other foot/leg behind or around the opposite leg as the blocking/hooking point.','Pull/control the ankle while pushing the hip away.','Use the opposite leg to prevent the recovery step.','As the opponent falls, keep enough control to stop them immediately standing.','Come up to top position.'],finish:'Follow to top while managing the legs so the opponent cannot technical-stand before you.',mechanism:'The three controls—ankle, hip, opposite leg—move the center while eliminating both stepping responses.',cues:['Own the ankle.','Push hip, block opposite leg.','Do not watch them fall—come up.'],mistakes:['Losing the ankle before the opponent is committed.','Hip foot too low/loose to move the center.','No control of the opposite recovery step.'],troubleshooting:[{problem:'They hop and stay standing.',fix:'Strengthen the opposite-leg block/hook and coordinate it with the hip push.'}],reactions:['If they retract one leg, switch to sickle/ankle-pull or wrestle-up options based on the new stance.'],followUps:['Sickle sweep','Ankle pull sweep','Technical stand-up'],variations:['Classic tripod sweep','Tripod from collar-sleeve/open guard'],drilling:['Build the three control points and pause.','Sweep slowly, then race only to establish top position.']},
'Sickle sweep':{goal:'Control one ankle and use your opposite leg as a low sweeping bar while the other foot shifts the opponent’s hips beyond their base.',setup:'Begin in open guard against a standing opponent, commonly as a complement to the tripod sweep.',grips:['Control the ankle that must not step away.','Use available upper-body control to keep the opponent connected while your legs change the base.'],baseManipulation:'Push/redirect the hip while the low sweeping leg removes the far leg and the hand fixes the near ankle.',bodyPosition:'Angle your hips so the sweeping leg can travel low across the opponent’s lower leg rather than kicking upward.',steps:['Secure the near ankle.','Place the opposite-side foot on the opponent’s hip to move their center.','Position the other leg low against/behind the far ankle or lower leg.','Push the hip while pulling/fixing the controlled ankle.','Sweep the far leg with a low sickle-like motion.','Maintain leg/ankle awareness as the opponent falls.','Come up immediately to top.'],finish:'Establish top position before releasing all lower-body controls.',mechanism:'The opponent loses both stepping options: one ankle is held while the other leg is swept as the hip is pushed beyond the support line.',cues:['Sweep low.','Control one ankle; remove the other.','Hip push moves the center.','Come up.'],mistakes:['Kicking high at the knee instead of sweeping low.','No hip movement.','Releasing the controlled ankle early.'],troubleshooting:[{problem:'Their far leg feels immovable.',fix:'Move their hips/weight first so the far foot becomes light before sweeping it.'}],reactions:['If the stance changes, transition to tripod or ankle-pull controls.'],followUps:['Tripod sweep','Ankle pull sweep','Top position'],variations:['Sickle sweep from open guard'],drilling:['Alternate tripod and sickle based on which leg the partner makes light.']},
'Ankle lock submission':{goal:'Control the opponent’s leg and ankle with your arms, ribs, hips, and lower-body position, then apply a straight ankle lock within your ruleset.',setup:'Enter from an academy-approved straight-ankle-lock position with the opponent’s foot captured and your own legs positioned safely.',grips:['Wrap the ankle so the blade of your forearm/wrist sits at the appropriate Achilles/ankle line taught by your coach.','Secure a reinforcing grip that removes slack without twisting into prohibited directions.'],baseManipulation:'Control the opponent’s knee/hip line so they cannot freely rotate, stand, or pull the leg out before you apply the finish.',bodyPosition:'Keep the captured foot tight to your ribs and your spine/hips aligned. Use whole-body extension rather than curling the arm alone.',steps:['Secure the opponent’s leg position before chasing the foot.','Capture the ankle deeply with the forearm at the correct line.','Clamp the foot to your ribs and remove slack from the grip.','Control the opponent’s knee/hip rotation with your leg configuration.','Align your torso and look/lean in the legal finishing direction.','Extend your hips/body gradually while keeping the ankle trapped.','Release immediately on the tap.'],finish:'Apply controlled straight-line ankle pressure only within the ruleset you are training. Never explosively bridge into a foot lock.',mechanism:'The forearm becomes a fulcrum at the ankle while your torso/hip extension bends the foot over that fulcrum and your leg control prevents escape.',cues:['Position before foot.','No slack.','Foot tight to ribs.','Whole body, slow finish.'],mistakes:['Trying to curl with the arms only.','Loose knee/hip control.','Foot too shallow in the armpit/ribs.','Applying prohibited rotational pressure.'],troubleshooting:[{problem:'They pull the foot free.',fix:'Secure the leg/knee line and deepen the ankle capture before extending.'},{problem:'My arms fatigue.',fix:'Remove slack and connect the foot to your ribs so your torso/hips—not biceps—create the finish.'}],reactions:['If the opponent clears the knee/hip line, prioritize position and safe re-guard/top transition rather than chasing the foot.'],followUps:['Top position','Open guard'],variations:['Straight ankle lock; exact leg configurations depend on academy and competition rules.'],drilling:['Drill position and grip without finishing.','Add slow finishing pressure with explicit tap awareness and coach supervision.']},
'Seated guard':{goal:'Use an upright, mobile bottom position to manage distance, establish grips, threaten wrestle-ups/sweeps, and avoid being flattened.',setup:'Sit facing the opponent with a balanced base, knees/feet positioned to move, and hands ready to grip or post safely.',grips:['Seek meaningful first connections: collar/sleeve in gi, wrist/arm/head/leg connections in no-gi.','Keep at least one hand available to post/frame when the opponent tries to collapse your posture.'],baseManipulation:'Make the passer react to your grips, feet, and forward threat. Do not allow them to stand comfortably over a passive seated posture.',bodyPosition:'Stay tall through the spine with your head over your hips enough to move forward. Avoid sitting square on both butt cheeks with your hands behind you.',steps:['Establish a balanced seated stance and protect inside space.','Make first contact with a useful grip rather than reaching without purpose.','Use your feet/shins to manage distance and prevent direct chest-to-chest pressure.','Create an angle instead of backing straight away.','Threaten a wrestle-up, collar drag, ankle control, or sweep so the passer must react.','If the opponent disengages, come forward and reclaim space.','If they collapse your posture, frame and rebuild height before attacking.'],finish:'Seated guard is a hub: finish by taking top, entering a sweep/takedown, or transitioning to a stronger guard rather than remaining static.',mechanism:'An upright posture allows your arms and legs to connect to the opponent while keeping your hips mobile enough to follow, stand, or attack their base.',cues:['Head up, hips mobile.','Make first contact meaningful.','Threaten forward—not only retreat.','If neither person controls the exchange, come up.'],mistakes:['Sitting flat and waiting for the pass.','Both hands posted behind you.','Reaching with straight arms and losing posture.','Backing away without creating an attack.'],troubleshooting:[{problem:'I keep getting flattened.',fix:'Protect your head/inside position, keep a hand available to frame, and rebuild upright posture before attacking.'},{problem:'They disengage and circle away.',fix:'Use the space to come forward/stand rather than following them from your butt.'}],reactions:['A retreating opponent invites you to stand or wrestle up.','Forward pressure creates collar-drag, underhook, shin-to-shin, or guard-transition opportunities.'],followUps:['Seated single · collar drag / wrist grip','Technical stand-up','Tripod sweep'],variations:['Gi seated guard','No-gi seated guard'],drilling:['Start seated versus a standing/kneeling partner; score only by establishing a meaningful connection or coming to top.','Add passing resistance progressively.']},
'Seated single · collar drag / wrist grip':{goal:'Use a collar/wrist connection from seated guard to pull the opponent past their base, connect to a leg/body, and wrestle up to top.',setup:'Begin seated and upright with the opponent within gripping range. Keep your posture mobile enough to move forward onto a knee.',grips:['In gi, a collar grip can drag the opponent’s upper body past their feet while the other hand connects to the leg/body.','A wrist/sleeve grip can remove a post and help you enter the single.','Once you come up, transition from loose hand grips to a strong leg/body connection.'],baseManipulation:'Drag or redirect the upper body so one leg becomes loaded/available. Remove the near post and come up into the space rather than trying to pull the opponent onto you.',bodyPosition:'Get off both butt cheeks and onto your side/knee as you enter. Keep your head connected safely to the opponent and your hips underneath you so you can drive.',steps:['Establish collar and/or wrist/sleeve control from seated guard.','Create a forward/sideways reaction with the drag.','As the opponent steps or posts, connect to the available near leg.','Get onto your side and then up to a knee; do not stay seated while holding the leg.','Bring your head and chest into a strong wrestling position.','Connect your hands around the leg/body as appropriate.','Identify the opponent’s remaining post and remove/trap it.','Drive, turn, or knee-pick according to the reaction and finish on top.'],finish:'Establish top control before releasing the leg/body connection.',mechanism:'The drag moves the opponent’s center and occupies a post; the wrestle-up converts the temporary imbalance into a standing/kneeling takedown rather than relying on a pure bottom sweep.',cues:['Drag → come up.','Do not admire the grip.','Head connected, hips underneath you.','Identify the post, remove it, take top.'],mistakes:['Pulling while remaining seated.','Reaching for the leg before creating a reaction.','Head disconnected from the opponent.','Stopping on the knees instead of finishing to top.'],troubleshooting:[{problem:'They pull the leg away before I can finish.',fix:'Come up sooner and connect your head/chest/body to them instead of holding the leg at arm’s length.'},{problem:'Their posting knee stops me.',fix:'Treat the knee as the problem: trap/remove it and continue the drive rather than starting over.'}],reactions:['If they retreat completely, technical-stand and reset to your standing game.','If they whizzer, improve head position and far-arm safety before closing the hips.'],followUps:['Underhook Knee Pick','Body Lock Trip','Technical stand-up'],variations:['Collar-drag single','Wrist/sleeve wrestle-up'],drilling:['Partner gives one predictable step/post; drag and come to a knee.','Progress to partner choosing retreat, post, or whizzer; solve the first layer and take top.']}
};

const detailedByName=new Map([...starterTechniques,...movementCompetencies].map(t=>[t.name.toLowerCase(),t]));
export const curriculumCompetencies:BjjTechnique[]=curriculumSeeds.flatMap(group=>group.names.map(name=>{
 const detailed=detailedByName.get(name.toLowerCase());
 if(detailed)return {...detailed,position:group.area};
 const instruction=guardBottomInstruction[name];
 if(instruction)return {id:'competency-'+slug(group.area)+'-'+slug(name),name,position:group.area,category:'Competency',applicability:['Gi','No-Gi'] as ('Gi'|'No-Gi')[],status:'Learning' as TechniqueStatus,competency:'Not assessed' as CompetencyStatus,tags:['Competency','Instruction complete'],setup:'',steps:[],cues:[],mistakes:[],followUps:[],notes:'',...instruction};
 return {id:'competency-'+slug(group.area)+'-'+slug(name),name,position:group.area,category:'Competency',applicability:['Gi','No-Gi'] as ('Gi'|'No-Gi')[],status:'Learning' as TechniqueStatus,competency:'Not assessed' as CompetencyStatus,tags:['Competency','Instruction pending'],setup:'',steps:[],cues:[],mistakes:[],followUps:[],notes:''};
}));
export function seedCompetencyTechniques(existing:BjjTechnique[]){
 const byName=new Map(existing.map(t=>[t.name.toLowerCase(),t]));
 const merged=[...existing];
 for(const seed of [...movementCompetencies,...curriculumCompetencies]){
  const current=byName.get(seed.name.toLowerCase());
  if(current){
   if(current.position!==seed.position){
    const i=merged.findIndex(t=>t.id===current.id);
    if(i>=0)merged[i]={...current,position:seed.position};
   }
  }else{merged.push(seed);byName.set(seed.name.toLowerCase(),seed)}
 }
 return merged
}
